import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#getPct(Object)
 */
public class Frequency_getPct_TriageGen0Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testGetPctWithInteger() {
        frequency.addValue(10);
        frequency.addValue(20);
        frequency.addValue(10);

        // Total count = 3. Count of 10 = 2. Pct = 2/3
        double expected = 2.0 / 3.0;
        double actual = frequency.getPct(10);
        Assert.assertEquals(expected, actual, 1e-10);
    }












}

