 */
public class Frequency_getPct_TriageGen0Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }











    @Test(expected = ClassCastException.class)
    public void testGetPctWithNonComparable() {
        // Creating a non-comparable object to trigger ClassCastException at (Comparable<?>) v
        class NonComparable {
            @Override
            public boolean equals(Object obj) { return false; }
        }
        frequency.addValue(1);
        frequency.getPct(new NonComparable());
    }


}

